#!/bin/bash
# Frame-parallel rendering of the modelwindfarm VDB series (dynamic queue, any number of nodes).
# Run one instance per node (srun -N1 -n1 -c 128 -w <node> ...). Each worker takes the next frame
# whose PNG is missing by an atomic mkdir claim in <out>/claims; resumable; FIRST/LAST/STRIDE
# select frames. Scenes (one XML per frame) are generated by the first worker (lock).
# Usage: render_series.sh <look: wake|vortex|combined> <WxH> <spp> <out_dir>
#   VDBDIR (default runs/modelwindfarm/case/VDB), FIRST=2005 LAST=3500 STEP=5 (time indices),
#   STRIDE=1 (render every n-th frame), NFRAMES=300 (camera path length).
#   FOLLOW=1: follow a running export (frames whose .vdb does not exist yet are retried every
#   20 s until all PNGs exist; mesioVDB writes <file>.tmp and renames it when complete).
D=/mnt/proj2/eu-25-121/milanjaros/openfoam/data/cyclesphi/scenes/modelwindfarm
source $D/looks.sh
LOOK=$1; RES=$2; SPP=$3; OUT=$4
VDBDIR=${VDBDIR:-/scratch/project/eu-25-121/milanjaros/openfoam/runs/modelwindfarm/case/VDB}
FIRST=${FIRST:-2005}; LAST=${LAST:-3500}; STEP=${STEP:-5}; STRIDE=${STRIDE:-1}; NFRAMES=${NFRAMES:-300}
ARGS_VAR=LOOK_$LOOK; ARGS=${!ARGS_VAR}
mkdir -p $OUT/claims $OUT/scene
if mkdir $OUT/scene/.lock 2>/dev/null; then
    files=(); for ((i=FIRST; i<=LAST; i+=STEP*STRIDE)); do files+=($(printf "%s/wf_%06d.vdb" $VDBDIR $i)); done
    python3 $D/make_windfarm_scene.py $ARGS --outdir $OUT/scene --frame-from-name --first $FIRST --step $STEP \
        --nframes $NFRAMES --vdb "${files[@]}" && touch $OUT/scene/.done
fi
while [ ! -f $OUT/scene/.done ]; do sleep 2; done
while true; do
    missing=0
    for ((i=FIRST; i<=LAST; i+=STEP*STRIDE)); do
        n=$(printf "wf_%06d" $i)
        [ -f $OUT/$n.png ] && continue
        [ -f $VDBDIR/$n.vdb ] || { missing=1; continue; }
        mkdir $OUT/claims/$n 2>/dev/null || continue
        bash $D/render_scenes.sh $RES $SPP $OUT $OUT/scene/$n.xml
    done
    [ "${FOLLOW:-0}" = 1 ] && [ $missing = 1 ] || break
    sleep 20
done
echo "$(hostname -s): done"
